const data = $input.first().json.body || $input.first().json;
const calories = parseFloat(data.calories) || 0;
const protein = parseFloat(data.protein) || 0;
const carbs = parseFloat(data.carbs) || 0;
const fat = parseFloat(data.fat) || 0;
const totalCal = (protein * 4) + (carbs * 4) + (fat * 9);
return [{ json: { ...data, calories, protein, carbs, fat, macro_split: { protein_pct: totalCal > 0 ? Math.round(protein * 4 / totalCal * 100) : 0, carbs_pct: totalCal > 0 ? Math.round(carbs * 4 / totalCal * 100) : 0, fat_pct: totalCal > 0 ? Math.round(fat * 9 / totalCal * 100) : 0 }, analyzed_at: new Date().toISOString() } }];

const meal = $input.first().json;
const CALORIE_GOAL = 2000;
return [{ json: { meal_logged: meal.food_name, meal_calories: meal.calories, macro_split: meal.macro_split, calorie_goal: CALORIE_GOAL, summary: meal.food_name + ' logged (' + meal.calories + ' kcal). Macros: P' + meal.protein + 'g C' + meal.carbs + 'g F' + meal.fat + 'g' } }];
